//! `waac-parity`: run the Rust mechanism on cases generated by the
//! Python reference and emit JSON results for comparison.
//!
//!   waac-parity <cases.json> [results.json]
//!
//! Case file format (written by `tests/parity_check.py`):
//!   {"cases": [{"kind": ..., ...}, ...]}
//! Each case kind and its output are documented in `parity_check.py`.
//! The binary reads stdin when the path is `-`.

use std::collections::{BTreeMap, HashMap};
use std::io::Read;
use waac_rs::json::{dumps_compact, obj, parse, Json};
use waac_rs::policy::{fuse, fuse_many, policy_satisfies, Need, Policy};
use waac_rs::waac::{
    canonical_key, effective_caps, fuse_policies, make_fragment,
    obligations_for_step, online_requirements, project_context,
    project_field, semantic_tokens, Field, Fragment, HistoryLibrary,
    InputSpec, OpNode, TraceDAG,
};

fn jstr(v: &Json) -> String {
    v.as_str().unwrap_or("").to_string()
}

fn jpolicy(v: &Json) -> Policy {
    Policy::from_name(v.as_str().unwrap_or("DROP")).unwrap_or(Policy::Drop)
}

fn jneed(v: &Json) -> Need {
    Need::from_name(v.as_str().unwrap_or("unresolved")).unwrap_or(Need::Unresolved)
}

fn parse_field(v: &Json) -> Field {
    Field::new(
        v.get("name").map(jstr).unwrap_or_default().as_str(),
        v.get("ftype").map(jstr).unwrap_or_default().as_str(),
        v.get("value").map(jstr).unwrap_or_default(),
        v.get("long_text").and_then(|x| x.as_bool()).unwrap_or(false),
        v.get("artifact_id").and_then(|x| x.as_str()).map(|s| s.to_string()),
    )
}

fn parse_dag(v: &Json) -> (TraceDAG, Vec<(usize, String, Need)>, Vec<(usize, String)>) {
    let mut nodes = Vec::new();
    for nv in v.get("nodes").and_then(|x| x.as_arr()).unwrap_or(&[]) {
        let mut inputs = Vec::new();
        for iv in nv.get("inputs").and_then(|x| x.as_arr()).unwrap_or(&[]) {
            let src = iv
                .get("source")
                .and_then(|s| s.as_arr())
                .map(|a| (a[0].as_i64().unwrap() as usize, a[1].as_str().unwrap().to_string()));
            inputs.push((
                iv.get("name").map(jstr).unwrap_or_default(),
                InputSpec {
                    source: src,
                    need: jneed(iv.get("need").unwrap()),
                    uncertain: iv.get("uncertain").and_then(|x| x.as_bool()).unwrap_or(false),
                },
            ));
        }
        let outputs: Vec<Field> = nv
            .get("outputs")
            .and_then(|x| x.as_arr())
            .unwrap_or(&[])
            .iter()
            .map(parse_field)
            .collect();
        nodes.push(OpNode::new(
            nv.get("op_type").map(jstr).unwrap_or_default().as_str(),
            inputs,
            outputs,
        ));
    }
    let uncertain: Vec<(usize, String)> = v
        .get("uncertain")
        .and_then(|x| x.as_arr())
        .unwrap_or(&[])
        .iter()
        .map(|u| {
            let a = u.as_arr().unwrap();
            (a[0].as_i64().unwrap() as usize, a[1].as_str().unwrap().to_string())
        })
        .collect();
    let final_needs: Vec<(usize, String, Need)> = v
        .get("final_needs")
        .and_then(|x| x.as_arr())
        .unwrap_or(&[])
        .iter()
        .map(|u| {
            let a = u.as_arr().unwrap();
            (
                a[0].as_i64().unwrap() as usize,
                a[1].as_str().unwrap().to_string(),
                jneed(&a[2]),
            )
        })
        .collect();
    (TraceDAG::new(nodes, uncertain), final_needs, vec![])
}

fn parse_fragment(v: &Json) -> Fragment {
    Fragment {
        ops: v
            .get("ops")
            .and_then(|x| x.as_arr())
            .unwrap_or(&[])
            .iter()
            .map(jstr)
            .collect(),
        fields: v
            .get("fields")
            .and_then(|x| x.as_arr())
            .unwrap_or(&[])
            .iter()
            .map(|f| {
                let a = f.as_arr().unwrap();
                (
                    a[0].as_i64().unwrap() as usize,
                    a[1].as_str().unwrap().to_string(),
                    a[2].as_str().unwrap().to_string(),
                )
            })
            .collect(),
        edges: v
            .get("edges")
            .and_then(|x| x.as_arr())
            .unwrap_or(&[])
            .iter()
            .map(|f| {
                let a = f.as_arr().unwrap();
                (
                    a[0].as_i64().unwrap() as usize,
                    a[1].as_str().unwrap().to_string(),
                    a[2].as_i64().unwrap() as usize,
                    a[3].as_str().unwrap().to_string(),
                )
            })
            .collect(),
        domain_words: v
            .get("domain_words")
            .and_then(|x| x.as_arr())
            .unwrap_or(&[])
            .iter()
            .map(jstr)
            .collect(),
    }
}

fn parse_policies(v: &Json) -> BTreeMap<(usize, String), Policy> {
    // Policies are encoded as {"0|field": "POLICY"} objects in the case file.
    let mut out2 = BTreeMap::new();
    if let Json::Obj(pairs) = v {
        for (k, p) in pairs {
            let (oi, fname) = k.split_once('|').unwrap();
            out2.insert(
                (oi.parse::<usize>().unwrap(), fname.to_string()),
                jpolicy(p),
            );
        }
    }
    out2
}

fn run_case(case: &Json) -> Json {
    let kind = case.get("kind").map(jstr).unwrap_or_default();
    match kind.as_str() {
        "fuse" => {
            let a = jpolicy(case.get("a").unwrap());
            let b = jpolicy(case.get("b").unwrap());
            let f = fuse(a, b);
            obj(&[
                ("kind", Json::Str("fuse".into())),
                ("result", Json::Str(f.name().into())),
                ("caps", Json::Int(f.caps() as i64)),
            ])
        }
        "fuse_many" => {
            let ps: Vec<Policy> = case
                .get("policies")
                .and_then(|x| x.as_arr())
                .unwrap_or(&[])
                .iter()
                .map(jpolicy)
                .collect();
            let f = fuse_many(ps);
            obj(&[
                ("kind", Json::Str("fuse_many".into())),
                ("result", Json::Str(f.name().into())),
            ])
        }
        "satisfies" => {
            let p = jpolicy(case.get("policy").unwrap());
            let n = jneed(case.get("need").unwrap());
            obj(&[
                ("kind", Json::Str("satisfies".into())),
                ("result", Json::Bool(policy_satisfies(p, n))),
            ])
        }
        "dag" => {
            // Random DAG: online requirements + fusion + projection.
            let (dag, final_needs, _) = parse_dag(case.get("dag").unwrap());
            let step = case.get("step").and_then(|x| x.as_i64()).unwrap_or(0) as usize;
            let obs = obligations_for_step(&dag, &final_needs, step);
            let online = online_requirements(&dag, &obs);
            let proposal = case.get("proposal").map(parse_policies);
            let fused = fuse_policies(&online, proposal.as_ref());
            let mut runtime: HashMap<String, String> = HashMap::new();
            if let Some(Json::Obj(pairs)) = case.get("runtime") {
                for (k, v) in pairs {
                    runtime.insert(k.clone(), jstr(v));
                }
            }
            let (rendered, caps, n_fb) =
                project_context(&dag, &fused, &runtime, step);
            let online_json: Vec<Json> = online
                .iter()
                .map(|((i, f), p)| {
                    Json::Arr(vec![
                        Json::Int(*i as i64),
                        Json::Str(f.clone()),
                        Json::Str(p.name().into()),
                    ])
                })
                .collect();
            let fused_json: Vec<Json> = fused
                .iter()
                .map(|((i, f), p)| {
                    Json::Arr(vec![
                        Json::Int(*i as i64),
                        Json::Str(f.clone()),
                        Json::Str(p.name().into()),
                    ])
                })
                .collect();
            let rendered_json: Vec<Json> = rendered
                .iter()
                .map(|((i, f), t)| {
                    Json::Arr(vec![
                        Json::Int(*i as i64),
                        Json::Str(f.clone()),
                        Json::Str(t.clone()),
                    ])
                })
                .collect();
            let caps_json: Vec<Json> = caps
                .iter()
                .map(|((i, f), c)| {
                    Json::Arr(vec![
                        Json::Int(*i as i64),
                        Json::Str(f.clone()),
                        Json::Int(*c as i64),
                    ])
                })
                .collect();
            obj(&[
                ("kind", Json::Str("dag".into())),
                ("online", Json::Arr(online_json)),
                ("fused", Json::Arr(fused_json)),
                ("rendered", Json::Arr(rendered_json)),
                ("caps", Json::Arr(caps_json)),
                ("n_fallbacks", Json::Int(n_fb as i64)),
            ])
        }
        "project_field" => {
            let field = parse_field(case.get("field").unwrap());
            let policy = jpolicy(case.get("policy").unwrap());
            let mut runtime: HashMap<String, String> = HashMap::new();
            if let Some(Json::Obj(pairs)) = case.get("runtime") {
                for (k, v) in pairs {
                    runtime.insert(k.clone(), jstr(v));
                }
            }
            let (text, fb) = project_field(&field, policy, &runtime);
            let caps = effective_caps(&field, policy, &runtime);
            obj(&[
                ("kind", Json::Str("project_field".into())),
                ("text", text.map(Json::Str).unwrap_or(Json::Null)),
                ("fell_back", Json::Bool(fb)),
                ("caps", Json::Int(caps as i64)),
            ])
        }
        "fragment" => {
            // Canonical key + semantic tokens + TF-IDF match against a
            // small library built from the case's entries.
            let frag = parse_fragment(case.get("fragment").unwrap());
            let key = canonical_key(&frag);
            let toks = semantic_tokens(&frag);
            let mut lib = HistoryLibrary::new();
            for e in case
                .get("entries")
                .and_then(|x| x.as_arr())
                .unwrap_or(&[])
            {
                let ef = parse_fragment(e.get("fragment").unwrap());
                let pols = e.get("policies").map(parse_policies).unwrap_or_default();
                lib.add_fragment(
                    ef,
                    &pols,
                    e.get("verified").and_then(|x| x.as_bool()).unwrap_or(true),
                    e.get("source_id").map(jstr).unwrap_or_default().as_str(),
                );
            }
            let m = lib.match_fragment(&frag, 0.5);
            let (m_idx, m_score, m_kind) = match m {
                Some((i, s, k)) => (Json::Int(i as i64), Json::Float(s), Json::Str(k.into())),
                None => (Json::Null, Json::Null, Json::Null),
            };
            obj(&[
                ("kind", Json::Str("fragment".into())),
                ("key", Json::Str(key)),
                ("tokens", Json::Arr(toks.into_iter().map(Json::Str).collect())),
                ("library_entries", Json::Int(lib.len() as i64)),
                ("match_index", m_idx),
                ("match_score", m_score),
                ("match_kind", m_kind),
            ])
        }
        "make_fragment" => {
            let (dag, _, _) = parse_dag(case.get("dag").unwrap());
            let start = case.get("start").and_then(|x| x.as_i64()).unwrap_or(0) as usize;
            let end = case.get("end").and_then(|x| x.as_i64()).unwrap_or(0) as usize;
            let words: Vec<String> = case
                .get("domain_words")
                .and_then(|x| x.as_arr())
                .unwrap_or(&[])
                .iter()
                .map(jstr)
                .collect();
            let frag = make_fragment(&dag, start, end, &words);
            let key = canonical_key(&frag);
            let frag_json = obj(&[
                ("ops", Json::Arr(frag.ops.iter().map(|s| Json::Str(s.clone())).collect())),
                ("fields", Json::Arr(frag.fields.iter().map(|(r, n, t)| Json::Arr(vec![Json::Int(*r as i64), Json::Str(n.clone()), Json::Str(t.clone())])).collect())),
                ("edges", Json::Arr(frag.edges.iter().map(|(a, b, c, d)| Json::Arr(vec![Json::Int(*a as i64), Json::Str(b.clone()), Json::Int(*c as i64), Json::Str(d.clone())])).collect())),
                ("domain_words", Json::Arr(frag.domain_words.iter().map(|s| Json::Str(s.clone())).collect())),
            ]);
            obj(&[
                ("kind", Json::Str("make_fragment".into())),
                ("fragment", frag_json),
                ("key", Json::Str(key)),
            ])
        }
        other => obj(&[
            ("kind", Json::Str(other.into())),
            ("error", Json::Str("unknown case kind".into())),
        ]),
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let path = args.first().cloned().unwrap_or_else(|| "-".to_string());
    let mut input = String::new();
    if path == "-" {
        std::io::stdin().read_to_string(&mut input).unwrap();
    } else {
        input = std::fs::read_to_string(&path).unwrap_or_else(|e| {
            eprintln!("cannot read {path}: {e}");
            std::process::exit(2);
        });
    }
    let doc = parse(&input).unwrap_or_else(|e| {
        eprintln!("cannot parse {path}: {e}");
        std::process::exit(2);
    });
    let cases = doc
        .get("cases")
        .and_then(|x| x.as_arr())
        .map(|a| a.to_vec())
        .unwrap_or_default();
    let results: Vec<Json> = cases.iter().map(run_case).collect();
    let out = obj(&[("results", Json::Arr(results))]);
    let text = dumps_compact(&out);
    if let Some(out_path) = args.get(1) {
        std::fs::write(out_path, text + "\n").unwrap_or_else(|e| {
            eprintln!("cannot write {out_path}: {e}");
            std::process::exit(2);
        });
    } else {
        println!("{text}");
    }
}
